        FontFace = fonts.watermark,
        TextSize = 16,
        TextColor3 = Color3.new(1, 1, 1),
        Size = UDim2.fromOffset(0, 18),
        AutomaticSize = Enum.AutomaticSize.X,
        ZIndex = 2,
    }, container)

    connect(label:GetPropertyChangedSignal("Text"), function()
        shadow.Text = label.Text
    end)

    return label
end

